        a1 = _mm256_blend_epi32(a1, t2, 0xAA);
        a3 = _mm256_blend_epi32(t3, a3, 0xAA);

        t0 = _mm256_slli_epi64(a1, 16);
        t1 = _mm256_srli_epi64(a0, 16);
        t2 = _mm256_slli_epi64(a3, 16);
        t3 = _mm256_srli_epi64(a2, 16);

        a0 = _mm256_blend_epi16(a0, t0, 0xAA);
        a1 = _mm256_blend_epi16(t1, a1, 0xAA);
        a2 = _mm256_blend_epi16(a2, t2, 0xAA);
        a3 = _mm256_blend_epi16(t3, a3, 0xAA);

        t0 = _mm256_slli_epi16(a1, 12);
