        t0 = _mm256_slli_epi16(a2, 8);
        t1 = _mm256_srli_epi16(a1, 4);
        a1 = _mm256_xor_si256(t0, t1);

        t0 = _mm256_slli_epi16(a3, 4);
        t1 = _mm256_srli_epi16(a2, 8);
        a2 = _mm256_xor_si256(t0, t1);

        t0 = _mm256_slli_epi32(a1, 16);
        t1 = _mm256_srli_epi32(a1, 16);
        t2 = _mm256_blend_epi16(a0, t0, 0xAA);
        t3 = _mm256_blend_epi16(a2, a0, 0xAA);
        t4 = _mm256_blend_epi16(t1, a2, 0xAA);

        t0 = _mm256_slli_epi64(t3, 32);
        t1 = _mm256_srli_epi64(t3, 32);
        a0 = _mm256_blend_epi32(t2, t0, 0xAA);
        a1 = _mm256_blend_epi32(t4, t2, 0xAA);
        a2 = _mm256_blend_epi32(t1, t4, 0xAA);

