        a1 = t1;
        a2 = t2;
        a3 = t3;

        t0 = _mm_slli_epi64(a2, 32);
        t1 = _mm_srli_epi64(a0, 32);
        t2 = _mm_slli_epi64(a3, 32);
        t3 = _mm_srli_epi64(a1, 32);

        a0 = _mm_blend_epi32(a0, t0, 0xA);
        a2 = _mm_blend_epi32(t1, a2, 0xA);
        a1 = _mm_blend_epi32(a1, t2, 0xA);
        a3 = _mm_blend_epi32(t3, a3, 0xA);

        t0 = _mm_slli_epi64(a1, 16);
        t1 = _mm_srli_epi64(a0, 16);
        t2 = _mm_slli_epi64(a3, 16);
        t3 = _mm_srli_epi64(a2, 16);

        a0 = _mm_blend_epi16(a0, t0, 0xAA);
        a1 = _mm_blend_epi16(t1, a1, 0xAA);
        a2 = _mm_blend_epi16(a2, t2, 0xAA);
        a3 = _mm_blend_epi16(t3, a3, 0xAA);

        t0 = _mm_slli_epi16(a1, 12);
