        t0 = _mm_slli_epi16(a2, 8);
        t1 = _mm_srli_epi16(a1, 4);
        a1 = _mm_xor_si128(t0, t1);

        t0 = _mm_slli_epi16(a3, 4);
        t1 = _mm_srli_epi16(a2, 8);
        a2 = _mm_xor_si128(t0, t1);

        t0 = _mm_slli_epi32(a1, 16);
        t1 = _mm_srli_epi32(a1, 16);
        t2 = _mm_blend_epi16(a0, t0, 0xAA);
        t3 = _mm_blend_epi16(a2, a0, 0xAA);
        t4 = _mm_blend_epi16(t1, a2, 0xAA);

        t0 = _mm_slli_epi64(t3, 32);
        t1 = _mm_srli_epi64(t3, 32);
        a0 = _mm_blend_epi32(t2, t0, 0xA);
        a1 = _mm_blend_epi32(t4, t2, 0xA);
        a2 = _mm_blend_epi32(t1, t4, 0xA);

        t2 = _mm_unpacklo_epi64(a0, a1);
        t3 = _mm_blend_epi32(a2, a0, 0xC);
