/*************************************************
* Name:        ntt
*
* Description: Number-theoretic transform (NTT) in R_q. Transforms the
*              coefficient representation of a into a representation
*              where each block of 4 coefficients corresponds to an
*              element of Zq[X]/(X^4 - zeta_i).
*
* Arguments:   - int16_t r[NTRUPLUS_N]: pointer to output vector; NTT
*                                       representation of a in the
*                                       product ring Zq[X]/(X^4 - zeta_i)
*              - const int16_t a[NTRUPLUS_N]: pointer to input vector of
*                                            coefficients of a in R_q
*
* Returns:     none.
**************************************************/
static inline void ntt(int16_t r[NTRUPLUS_N])
{
	int16_t t1,t2,t3;
	uint32_t T1,T2;
	uint32_t zeta[7];
	int16_t v[8];

	int index = 1;

	zeta[0] = zetas[index++];

	for(int i = 0; i < NTRUPLUS_N/2; i++)
	{
		t1 = plantard_mul(zetas[1], r[i + NTRUPLUS_N/2]);

		r[i + NTRUPLUS_N/2] = r[i] + r[i + NTRUPLUS_N/2] - t1;
		r[i               ] = r[i]                       + t1;
	}

	for(int start = 0; start < NTRUPLUS_N; start += 576)
	{
		zeta[0] = zetas[index++];
		zeta[1] = zetas[index++];

		for(int i = start; i < start + 192; i++)
		{
			t1 = plantard_mul(zeta[0], r[i + 192]);
			t2 = plantard_mul(zeta[1], r[i + 384]);
			t3 = plantard_mul(NTRUPLUS_OMEGA, t1 - t2);

			r[i + 384] = r[i] - t1 - t3;
			r[i + 192] = r[i] - t2 + t3;
			r[i      ] = r[i] + t1 + t2;
		}
	}

	for (int i = 0; i < 6; i++)
	{
		zeta[0] = zetas[6+2*i];
		zeta[1] = zetas[7+2*i];
		zeta[2] = zetas[18+3*i];
		zeta[3] = zetas[19+3*i];
		zeta[4] = zetas[20+3*i];

		for (int j = 0; j < 32; j++)
		{
			for (int k = 0; k < 6; k++)
			{
				v[k] = r[32*k+j+192*i];
			}

			t1 = plantard_mul(zeta[0], v[2]);
			t2 = plantard_mul(zeta[1], v[4]);
			t3 = plantard_mul(NTRUPLUS_OMEGA, t1 - t2);
			v[4] = v[0] - t1 - t3;
			v[2] = v[0] - t2 + t3;
			v[0] = v[0] + t1 + t2;

			t1 = plantard_mul(zeta[0], v[3]);
			t2 = plantard_mul(zeta[1], v[5]);
			t3 = plantard_mul(NTRUPLUS_OMEGA, t1 - t2);
			v[5] = v[1] - t1 - t3;
			v[3] = v[1] - t2 + t3;
			v[1] = v[1] + t1 + t2;

			t1 = plantard_mul(zeta[2], v[1]);
			v[1] = v[0] - t1;
			v[0] = v[0] + t1;

			t1 = plantard_mul(zeta[3], v[3]);
			v[3] = v[2] - t1;
			v[2] = v[2] + t1;

			t1 = plantard_mul(zeta[4], v[5]);
			v[5] = v[4] - t1;
			v[4] = v[4] + t1;

			for (int k = 0; k < 6; k++)
			{
				r[32*k+j+192*i] = v[k];
			}
		}
	}

	for (int i = 0; i < 36; i++)
	{
		zeta[0] = zetas[36+i];
		zeta[1] = zetas[72+2*i];
		zeta[2] = zetas[73+2*i];
		zeta[3] = zetas[144+4*i];
		zeta[4] = zetas[145+4*i];
		zeta[5] = zetas[146+4*i];
		zeta[6] = zetas[147+4*i];

		for (int j = 0; j < 4; j++)
		{
			for (int k = 0; k < 8; k++)
			{
				v[k] = r[4*k+j+32*i];
			}

			t1 = plantard_mul(zeta[0], v[4]);
			v[4] = v[0] - t1;
			v[0] = v[0] + t1;

			t1 = plantard_mul(zeta[0], v[5]);
			v[5] = v[1] - t1;
			v[1] = v[1] + t1;

			t1 = plantard_mul(zeta[0], v[6]);
			v[6] = v[2] - t1;
			v[2] = v[2] + t1;

			t1 = plantard_mul(zeta[0], v[7]);
			v[7] = v[3] - t1;
			v[3] = v[3] + t1;

			t1 = plantard_mul(zeta[1], v[2]);
			v[2] = v[0] - t1;
			v[0] = v[0] + t1;

			t1 = plantard_mul(zeta[1], v[3]);
			v[3] = v[1] - t1;
			v[1] = v[1] + t1;

			t1 = plantard_mul(zeta[2], v[6]);
			v[6] = v[4] - t1;
			v[4] = v[4] + t1;

			t1 = plantard_mul(zeta[2], v[7]);
			v[7] = v[5] - t1;
			v[5] = v[5] + t1;

			T1 = v[0]*NTRUPLUS_R;
			T2 = v[1]*zeta[3];
			v[1] = plantard_reduce_acc(T1 - T2);
			v[0] = plantard_reduce_acc(T1 + T2);

			T1 = v[2]*NTRUPLUS_R;
			T2 = v[3]*zeta[4];
			v[3] = plantard_reduce_acc(T1 - T2);
			v[2] = plantard_reduce_acc(T1 + T2);

			T1 = v[4]*NTRUPLUS_R;
			T2 = v[5]*zeta[5];
			v[5] = plantard_reduce_acc(T1 - T2);
			v[4] = plantard_reduce_acc(T1 + T2);

			T1 = v[6]*NTRUPLUS_R;
			T2 = v[7]*zeta[6];
			v[7] = plantard_reduce_acc(T1 - T2);
			v[6] = plantard_reduce_acc(T1 + T2);

			for (int k = 0; k < 8; k++)
			{
				r[4*k+j+32*i] = v[k];
			}
		}
	}
}

/*************************************************
* Name:        poly_ntt
*
* Description: Computes number-theoretic transform (NTT)
*
* Arguments:   - poly *r: pointer to input/output polynomial
**************************************************/
void poly_ntt(poly *r)
{
	ntt(r->coeffs);
}

/*************************************************
* Name:        invntt
*
* Description: Inverse number-theoretic transform (NTT) in R_q. Transforms
*              the NTT representation in r, where each block of 4
*              coefficients corresponds to an element of Zq[X]/(X^4 - zeta_i),
*              back to the coefficient representation in R_q.
*
* Arguments:   - int16_t r[NTRUPLUS_N]: pointer to input/output vector;
*                                       input NTT representation in the
*                                       product ring Zq[X]/(X^4 - zeta_i),
*                                       output coefficient representation
*                                       in R_q
*
* Returns:     none.
**************************************************/
static inline void invntt(int16_t r[NTRUPLUS_N])
{
	int16_t t1,t2,t3;
	uint32_t zeta[7];
	int16_t v[8];

	for (int i = 0; i < 36; i++)
	{
		zeta[0] = zetas[287-4*i];
		zeta[1] = zetas[286-4*i];
		zeta[2] = zetas[285-4*i];
		zeta[3] = zetas[284-4*i];
		zeta[4] = zetas[143-2*i];
		zeta[5] = zetas[142-2*i];
		zeta[6] = zetas[71-i];

		for (int j = 0; j < 4; j++)
		{
			for (int k = 0; k < 8; k++)
			{
				v[k] = r[4*k+j+32*i];
			}

			t1 = v[1];
			v[1] = plantard_mul(zeta[0],  t1 - v[0]);
			v[0] = v[0] + t1;

			t1 = v[3];
			v[3] = plantard_mul(zeta[1],  t1 - v[2]);
			v[2] = v[2] + t1;

			t1 = v[5];
			v[5] = plantard_mul(zeta[2],  t1 - v[4]);
			v[4] = v[4] + t1;

			t1 = v[7];
			v[7] = plantard_mul(zeta[3],  t1 - v[6]);
			v[6] = v[6] + t1;

			t1 = v[2];
			v[2] = plantard_mul(zeta[4],  t1 - v[0]);
			v[0] = v[0] + t1;

			t1 = v[3];
			v[3] = plantard_mul(zeta[4],  t1 - v[1]);
			v[1] = v[1] + t1;

			t1 = v[6];
			v[6] = plantard_mul(zeta[5],  t1 - v[4]);
			v[4] = v[4] + t1;

			t1 = v[7];
			v[7] = plantard_mul(zeta[5],  t1 - v[5]);
			v[5] = v[5] + t1;

			t1 = v[4];
			v[4] = plantard_mul(zeta[6],  t1 - v[0]);
			v[0] = v[0] + t1;

			t1 = v[5];
			v[5] = plantard_mul(zeta[6],  t1 - v[1]);
			v[1] = v[1] + t1;

			t1 = v[6];
			v[6] = plantard_mul(zeta[6],  t1 - v[2]);
			v[2] = v[2] + t1;

			t1 = v[7];
			v[7] = plantard_mul(zeta[6],  t1 - v[3]);
			v[3] = v[3] + t1;

			for (int k = 0; k < 8; k++)
			{
				r[4*k+j+32*i] = v[k];
			}
		}
	}

	for (int i = 0; i < 6; i++)
	{
		zeta[0] = zetas[35-3*i];
		zeta[1] = zetas[34-3*i];
		zeta[2] = zetas[33-3*i];
		zeta[3] = zetas[16-2*i];
		zeta[4] = zetas[17-2*i];

		for (int j = 0; j < 32; j++)
		{
			for (int k = 0; k < 6; k++)
			{
				v[k] = r[32*k+j+192*i];
			}

			t1 = v[1];
			v[1] = plantard_mul(zeta[0],  t1 - v[0]);
			v[0] = v[0] + t1;

			t1 = v[3];
			v[3] = plantard_mul(zeta[1],  t1 - v[2]);
			v[2] = v[2] + t1;

			t1 = v[5];
			v[5] = plantard_mul(zeta[2],  t1 - v[4]);
			v[4] = v[4] + t1;

			t1 = plantard_mul(NTRUPLUS_OMEGA,    v[2] - v[0]);
			t2 = plantard_mul(zeta[3], v[4] - v[0] + t1);
			t3 = plantard_mul(zeta[4], v[4] - v[2] - t1);
			v[0] = plantard_mul((int32_t)v[0] + (int32_t)v[2] + (int32_t)v[4], NTRUPLUS_R);
			v[2] = t2;
			v[4] = t3;

			t1 = plantard_mul(NTRUPLUS_OMEGA,    v[3] - v[1]);
			t2 = plantard_mul(zeta[3], v[5] - v[1] + t1);
			t3 = plantard_mul(zeta[4], v[5] - v[3] - t1);
			v[1] = plantard_mul((int32_t)v[1] + (int32_t)v[3] + (int32_t)v[5], NTRUPLUS_R);
			v[3] = t2;
			v[5] = t3;

			for (int k = 0; k < 6; k++)
			{
				r[32*k+j+192*i] = v[k];
			}
		}
	}

	zeta[0] = zetas[4];
	zeta[1] = zetas[5];
	zeta[2] = zetas[2];
	zeta[3] = zetas[3];

	for (int i = 0; i < 192; i++)
	{
		for (int j = 0; j < 6; j++)
		{
			v[j] = r[192*j+i];
		}

		t1 = plantard_mul(NTRUPLUS_OMEGA,    v[1] - v[0]);
		t2 = plantard_mul(zeta[0], v[2] - v[0] + t1);
		t3 = plantard_mul(zeta[1], v[2] - v[1] - t1);
		v[0] = v[0] + v[1] + v[2];
		v[1] = t2;
		v[2] = t3;

		t1 = plantard_mul(NTRUPLUS_OMEGA,    v[4] - v[3]);
		t2 = plantard_mul(zeta[2], v[5] - v[3] + t1);
		t3 = plantard_mul(zeta[3], v[5] - v[4] - t1);
		v[3] = v[3] + v[4] + v[5];
		v[4] = t2;
		v[5] = t3;

		t1 = v[0] + v[3];
		t2 = plantard_mul(NTRUPLUS_ZMINUSZ5INV, v[0] - v[3]);
		v[0] = plantard_mul(NTRUPLUS_NINV, t1 - t2);
		v[3] = plantard_mul(NTRUPLUS_2NINV, t2);

		t1 = v[1] + v[4];
		t2 = plantard_mul(NTRUPLUS_ZMINUSZ5INV, v[1] - v[4]);
		v[1] = plantard_mul(NTRUPLUS_NINV, t1 - t2);
		v[4] = plantard_mul(NTRUPLUS_2NINV, t2);

		t1 = v[2] + v[5];
		t2 = plantard_mul(NTRUPLUS_ZMINUSZ5INV, v[2] - v[5]);
		v[2] = plantard_mul(NTRUPLUS_NINV, t1 - t2);
		v[5] = plantard_mul(NTRUPLUS_2NINV, t2);

		for (int j = 0; j < 6; j++)
		{
			r[192*j+i] = v[j];
		}
	}
}

/*************************************************
* Name:        poly_invntt
*
* Description: Computes inverse of number-theoretic transform (NTT)
*
* Arguments:   - poly *r: pointer to input/output polynomial
**************************************************/
void poly_invntt(poly *r)
{
	invntt(r->coeffs);
}


/*************************************************
* Name:        baseinv
*
* Description: Simultaneous inversion of polynomials in
*              Z_q[X]/(X^4 - zeta) and Z_q[X]/(X^4 + zeta), used as
*              a building block for inversion of elements in R_q in the
*              NTT domain. The input array a encodes two degree-3
*              polynomials:
*                a[0..3] for X^4 - zeta,
*                a[4..7] for X^4 + zeta.
*              On success, r[0..3] and r[4..7] contain their inverses.
*
* Arguments:   - int16_t r[8]:       pointer to the output polynomials
*              - const int16_t a[8]: pointer to the input polynomials
*              - uint32_t zeta:      parameter defining X^4 ± zeta
*
* Returns:     0 if both polynomials are invertible, 1 otherwise.
**************************************************/
static inline int baseinv_1(int16_t r[8], int16_t den[2], const int16_t a[8], uint32_t zeta)
{
	int16_t t0, t1, t2, t3;
	int16_t s0, s1, s2, s3;
	uint32_t A0, A1, A2, A3;
	uint32_t B0, B1, B2, B3;
	uint32_t zeta1, zeta2;

	zeta1 = zeta;
	zeta2 = -zeta;

	A0 = (int32_t)a[0]*NTRUPLUS_QINV;
	A1 = (int32_t)a[1]*NTRUPLUS_QINV;
	A2 = (int32_t)a[2]*NTRUPLUS_QINV;
	A3 = (int32_t)a[3]*NTRUPLUS_QINV;
	B0 = (int32_t)a[4]*NTRUPLUS_QINV;
	B1 = (int32_t)a[5]*NTRUPLUS_QINV;
	B2 = (int32_t)a[6]*NTRUPLUS_QINV;
	B3 = (int32_t)a[7]*NTRUPLUS_QINV;

	t0 = plantard_reduce_acc(a[2]*A2 - 2*a[1]*A3);
	s0 = plantard_reduce_acc(a[6]*B2 - 2*a[5]*B3);
	t1 = plantard_reduce_acc(a[3]*A3);
	s1 = plantard_reduce_acc(a[7]*B3);
	t0 = plantard_reduce_acc(a[0]*A0 + t0*zeta1);
	s0 = plantard_reduce_acc(a[4]*B0 + s0*zeta2);
	t1 = plantard_reduce_acc(a[1]*A1 + t1*zeta1 - 2*a[0]*A2);
	s1 = plantard_reduce_acc(a[5]*B1 + s1*zeta2 - 2*a[4]*B2);
	t2 = plantard_reduce_acc(t1*zeta1);
	s2 = plantard_reduce_acc(s1*zeta2);

	t3 = plantard_reduce(t0*t0 - t1*t2);
	s3 = plantard_reduce(s0*s0 - s1*s2);

	if (!(t3 && s3))
		return 1;

	r[0] = plantard_reduce_acc(A0*t0 + A2*t2);
	r[1] = plantard_reduce_acc(A3*t2 + A1*t0);
	r[2] = plantard_reduce_acc(A2*t0 + A0*t1);
	r[3] = plantard_reduce_acc(A1*t1 + A3*t0);
	r[4] = plantard_reduce_acc(B0*s0 + B2*s2);
	r[5] = plantard_reduce_acc(B3*s2 + B1*s0);
	r[6] = plantard_reduce_acc(B2*s0 + B0*s1);
	r[7] = plantard_reduce_acc(B1*s1 + B3*s0);

	den[0] = t3; /* R^-3 */
	den[1] = s3; /* R^-3 */

	return 0;
}


/*************************************************
* Name:        basemul
*
* Description: Multiplication of polynomials in Zq[X]/(X^4 - zeta),
*              used for multiplication of elements in R_q in the NTT domain.
*
* Arguments:   - int16_t r[4]:        pointer to the output polynomial
*              - const int16_t a[4]:  pointer to the first factor
*              - const int16_t b[4]:  pointer to the second factor
*              - const int16_t zeta:  parameter defining X^4 - zeta
*
* Returns:     none.
**************************************************/
static inline void basemul(int16_t r[4], const int16_t a[4], const int16_t b[4], const int16_t zeta)
{
	r[0] = montgomery_reduce(a[1]*b[3]+a[2]*b[2]+a[3]*b[1]); /* R^-1 */
	r[1] = montgomery_reduce(a[2]*b[3]+a[3]*b[2]);           /* R^-1 */
	r[2] = montgomery_reduce(a[3]*b[3]);                     /* R^-1 */

	r[0] = montgomery_reduce(r[0]*zeta+a[0]*b[0]);  				   /* R^-1 */
	r[1] = montgomery_reduce(r[1]*zeta+a[0]*b[1]+a[1]*b[0]); 		   /* R^-1 */
	r[2] = montgomery_reduce(r[2]*zeta+a[0]*b[2]+a[1]*b[1]+a[2]*b[0]); /* R^-1 */
	r[3] = montgomery_reduce(a[0]*b[3]+a[1]*b[2]+a[2]*b[1]+a[3]*b[0]); /* R^-1 */
}

#else
# error "unsupported NTRU+ C polynomial parameter set"
#endif
#endif

#ifdef NTRUPLUS_SOURCE_AVX2
int poly_baseinv(poly *r, const poly *a)
{
    __m256i den[NTRUPLUS_AVX2_DENVECTORS];
    int ret = 1;

    poly_baseinv_1(r, den, a);

    if (fqinv_batch(den)) {
        OPENSSL_cleanse(r->coeffs, NTRUPLUS_N * sizeof(int16_t));
        goto end;
    }

    poly_baseinv_2(r, den);
    ret = 0;

end:
    OPENSSL_cleanse(den, sizeof(den));
    return ret;
}
#endif

#ifndef NTRUPLUS_SOURCE_AVX2
int poly_baseinv(poly *r, const poly *a)
{
# if NTRUPLUS_D == 4
    int16_t den[NTRUPLUS_N / 4];
    const size_t zeta_offset = (NTRUPLUS_N == 768) ? 96 : 144;
    size_t i;

    for (i = 0; i < NTRUPLUS_N / 8; i++) {
        if (baseinv_1(r->coeffs + 8 * i, den + 2 * i,
                      a->coeffs + 8 * i, zetas[zeta_offset + i])) {
            OPENSSL_cleanse(r->coeffs, NTRUPLUS_N * sizeof(int16_t));
            OPENSSL_cleanse(den, sizeof(den));
            return 1;
        }
    }

    fqinv_batch(den);

    for (i = 0; i < NTRUPLUS_N / 4; i++)
        baseinv_2(r->coeffs + 4 * i, den + i);
    OPENSSL_cleanse(den, sizeof(den));
# elif NTRUPLUS_D == 3
    int16_t den[NTRUPLUS_N / 3];
    size_t i;

    for (i = 0; i < NTRUPLUS_N / 6; i++) {
        if (baseinv_1(r->coeffs + 6 * i, den + 2 * i,
                      a->coeffs + 6 * i, zetas[144 + i])) {
            OPENSSL_cleanse(r->coeffs, NTRUPLUS_N * sizeof(int16_t));
            OPENSSL_cleanse(den, sizeof(den));
            return 1;
        }
    }

    fqinv_batch(den);

    for (i = 0; i < NTRUPLUS_N / 3; i++)
        baseinv_2(r->coeffs + 3 * i, den + i);
    OPENSSL_cleanse(den, sizeof(den));
# else
#  error "unsupported NTRU+ C polynomial degree"
# endif

    return 0;
}

void poly_basemul(poly *r, const poly *a, const poly *b)
{
    size_t i;

# if NTRUPLUS_D == 4
    const size_t zeta_offset = (NTRUPLUS_N == 768) ? 96 : 144;

    for (i = 0; i < NTRUPLUS_N / 8; i++) {
        basemul(r->coeffs + 8 * i, a->coeffs + 8 * i,
                b->coeffs + 8 * i, zetas_mont[zeta_offset + i]);
        basemul(r->coeffs + 8 * i + 4, a->coeffs + 8 * i + 4,
                b->coeffs + 8 * i + 4, -zetas_mont[zeta_offset + i]);
    }
# elif NTRUPLUS_D == 3
    for (i = 0; i < NTRUPLUS_N / (2 * NTRUPLUS_D); i++) {
        basemul(r->coeffs + 6 * i, a->coeffs + 6 * i,
                b->coeffs + 6 * i, zetas_mont[144 + i]);
        basemul(r->coeffs + 6 * i + 3, a->coeffs + 6 * i + 3,
                b->coeffs + 6 * i + 3, -zetas_mont[144 + i]);
    }
# else
#  error "unsupported NTRU+ C polynomial degree"
# endif

    for (i = 0; i < NTRUPLUS_N; i++)
        r->coeffs[i] = montgomery_reduce(r->coeffs[i] * NTRUPLUS_RSQ_MONT);
}

void poly_basemul_add(poly *r, const poly *a, const poly *b, const poly *c)
{
    size_t i;

# if NTRUPLUS_D == 4
    const size_t zeta_offset = (NTRUPLUS_N == 768) ? 96 : 144;

    for (i = 0; i < NTRUPLUS_N / 8; i++) {
        basemul(r->coeffs + 8 * i, a->coeffs + 8 * i,
                b->coeffs + 8 * i, zetas_mont[zeta_offset + i]);
        basemul(r->coeffs + 8 * i + 4, a->coeffs + 8 * i + 4,
                b->coeffs + 8 * i + 4, -zetas_mont[zeta_offset + i]);
    }
# elif NTRUPLUS_D == 3
    for (i = 0; i < NTRUPLUS_N / (2 * NTRUPLUS_D); i++) {
        basemul(r->coeffs + 6 * i, a->coeffs + 6 * i,
                b->coeffs + 6 * i, zetas_mont[144 + i]);
        basemul(r->coeffs + 6 * i + 3, a->coeffs + 6 * i + 3,
                b->coeffs + 6 * i + 3, -zetas_mont[144 + i]);
    }
# else
#  error "unsupported NTRU+ C polynomial degree"
# endif

    for (i = 0; i < NTRUPLUS_N; i++)
        r->coeffs[i] = montgomery_reduce(c->coeffs[i] * NTRUPLUS_R_MONT
                                         + r->coeffs[i] * NTRUPLUS_RSQ_MONT);
}

void poly_tobytes(uint8_t r[NTRUPLUS_POLYBYTES], const poly *a)
{
    int16_t t[2];
    size_t i;

    for (i = 0; i < NTRUPLUS_N / 2; i++) {
        t[0] = a->coeffs[2 * i];
        t[0] += (t[0] >> 15) & NTRUPLUS_Q;
        t[1] = a->coeffs[2 * i + 1];
        t[1] += (t[1] >> 15) & NTRUPLUS_Q;

        r[3 * i + 0] = (uint8_t)(t[0] >> 0);
        r[3 * i + 1] = (uint8_t)((t[0] >> 8) | (t[1] << 4));
        r[3 * i + 2] = (uint8_t)(t[1] >> 4);
    }
}

void poly_frombytes(poly *r, const uint8_t a[NTRUPLUS_POLYBYTES])
{
    size_t i;

    for (i = 0; i < NTRUPLUS_N / 2; i++) {
        r->coeffs[2 * i] =
            ((a[3 * i + 0] >> 0) | ((uint16_t)a[3 * i + 1] << 8)) & 0xfff;
        r->coeffs[2 * i + 1] =
            ((a[3 * i + 1] >> 4) | ((uint16_t)a[3 * i + 2] << 4)) & 0xfff;
    }
}

void poly_cbd1(poly *r, const uint8_t buf[NTRUPLUS_N / 4])
{
    uint8_t t1, t2;
    size_t i, j;

    for (i = 0; i < NTRUPLUS_N / 8; i++) {
        t1 = buf[i];
        t2 = buf[i + NTRUPLUS_N / 8];

        for (j = 0; j < 8; j++) {
            r->coeffs[8 * i + j] = (t1 & 0x1) - (t2 & 0x1);
            t1 >>= 1;
            t2 >>= 1;
        }
    }
}

void poly_sotp_encode(poly *r, const uint8_t msg[NTRUPLUS_N / 8],
                      const uint8_t buf[NTRUPLUS_N / 4])
{
    uint8_t tmp[NTRUPLUS_N / 4];
    int i;

    for (i = 0; i < NTRUPLUS_N / 8; i++)
        tmp[i] = buf[i] ^ msg[i];

    for (i = NTRUPLUS_N / 8; i < NTRUPLUS_N / 4; i++)
        tmp[i] = buf[i];

    poly_cbd1(r, tmp);
}

int poly_sotp_decode(uint8_t msg[NTRUPLUS_N / 8], const poly *a,
                     const uint8_t buf[NTRUPLUS_N / 4])
{
    uint8_t t1, t2, t3;
    uint16_t t4;
    uint32_t r = 0;
    uint8_t mask;
    size_t i, j;

    for (i = 0; i < NTRUPLUS_N / 8; i++) {
        t1 = buf[i];
        t2 = buf[i + NTRUPLUS_N / 8];
        t3 = 0;

        for (j = 0; j < 8; j++) {
            t4 = t2 & 0x1;
            t4 += a->coeffs[8 * i + j];
            r |= t4;
            t4 = (t4 ^ t1) & 0x1;
            t3 ^= (uint8_t)(t4 << j);

            t1 >>= 1;
            t2 >>= 1;
        }

        msg[i] = t3;
    }

    r = r >> 1;
    r = (-(uint32_t)r) >> 31;

    mask = (uint8_t)(r - 1);

    for (i = 0; i < NTRUPLUS_N / 8; i++)
        msg[i] &= mask;

    return r;
}

void poly_sub(poly *r, const poly *a, const poly *b)
{
    int i;

    for (i = 0; i < NTRUPLUS_N; i++)
        r->coeffs[i] = a->coeffs[i] - b->coeffs[i];
}

void poly_triple(poly *r, const poly *a)
{
    int i;

    for (i = 0; i < NTRUPLUS_N; i++)
        r->coeffs[i] = 3 * a->coeffs[i];
}

static inline int16_t crepmod3(int16_t a)
{
    int16_t t;
    const int16_t v = ((1 << 15) + 3 / 2) / 3;

    a += (a >> 15) & NTRUPLUS_Q;
    a -= (NTRUPLUS_Q + 1) / 2;
    a += (a >> 15) & NTRUPLUS_Q;
    a -= (NTRUPLUS_Q - 1) / 2;

    t = ((int32_t)v * a + (1 << 14)) >> 15;
    t *= 3;
    return a - t;
}

void poly_crepmod3(poly *r, const poly *a)
{
    int i;

    for (i = 0; i < NTRUPLUS_N; i++)
        r->coeffs[i] = crepmod3(a->coeffs[i]);
}
#endif

#ifdef NTRUPLUS_SOURCE_AVX2
void poly_basemul_add(poly *r, const poly *a, const poly *b, const poly *c)
{
    poly_basemul(r, a, b);
    poly_add(r, r, c);
}
#endif
